def binary_search(arr, target):
    # 生效条件：arr 为升序排列的数值列表；target 为查找目标
    # 子功能：① 双指针夹逼 ② 中位比较 ③ 找到返回索引
    # 执行：循环迭代（lo/hi 收缩）
    # 不适用条件：未排序列表结果不可靠（前置条件违背）；返回 -1 表示不存在
    lo, hi = 0, len(arr) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1

def bubble_sort(arr):
    # 生效条件：arr 为数值列表
    # 子功能：① 相邻比较交换 ② 每轮冒出最大值到尾部 ③ 返回新列表
    # 执行：双重循环迭代
    # 不适用条件：不修改原列表（返回新列表）；大列表效率低（O(n²)）
    result = list(arr)
    n = len(result)
    for i in range(n - 1):
        for j in range(n - 1 - i):
            if result[j] > result[j + 1]:
                result[j], result[j + 1] = result[j + 1], result[j]
    return result
